From 26fc8624beb3355cc474f9e75a20b051a114f0b2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 23:12:00 +0100
Subject: [PATCH] applets/kickoff: show recent applications and files in the
 sidebar

Recent apps and files were only reachable through Places > History,
four clicks away. Show them as categories right below Favorites; like
in Kicker, they can be hidden from their context menu or the settings.

BUG: 442981
---
 applets/kickoff/ApplicationsPage.qml | 15 ++++++++-------
 applets/kickoff/ConfigGeneral.qml    | 17 +++++++++++++++++
 applets/kickoff/main.qml             | 12 ++++++++++--
 applets/kickoff/main.xml             |  8 ++++++++
 4 files changed, 43 insertions(+), 9 deletions(-)

diff --git a/applets/kickoff/ApplicationsPage.qml b/applets/kickoff/ApplicationsPage.qml
index 76a058faec..3959d5bc1c 100644
--- a/applets/kickoff/ApplicationsPage.qml
+++ b/applets/kickoff/ApplicationsPage.qml
@@ -148,7 +148,8 @@ BasePage {
         // NOTE: The 0 index modelForRow isn't supposed to be used. That's just how it works.
         // But to trigger model data update, set initial value to 0
         property int appsModelRow: 0
-        readonly property Kicker.AppsModel appsModel: kickoff.rootModel.modelForRow(appsModelRow)
+        readonly property QtObject appsModel: kickoff.rootModel.modelForRow(appsModelRow)
+        readonly property bool showingAllApps: appsModel?.description === "KICKER_ALL_MODEL"
         Connections {
             target: kickoff.rootModel
             function onRefreshed() { // recalculate appsModel binding on rootModel refresh;
@@ -197,7 +198,7 @@ BasePage {
                 // we want to semantically switch between group and "", disabling grouping, workaround for QTBUG-121797
                 section.property: model && model.description === "KICKER_ALL_MODEL" ? "group" : "_unset"
                 section.criteria: ViewSection.FirstCharacter
-                hasSectionView: stackView.appsModelRow === 1
+                hasSectionView: stackView.showingAllApps

                 onShowSectionViewRequested: sectionName => {
                     stackView.showSectionView(sectionName, this);
@@ -239,7 +240,7 @@ BasePage {
                 id: listOfGridsView
                 objectName: "listOfGridsView"
                 mainContentView: true
-                gridModel: stackView.appsModel
+                gridModel: stackView.appsModel as Kicker.AppsModel

                 onShowSectionViewRequested: sectionName => {
                     stackView.showSectionView(sectionName, this);
@@ -253,12 +254,12 @@ BasePage {
             }
         }
         onPreferredAllAppsViewComponentChanged: {
-            if (root.sideBarItem !== null && root.sideBarItem.currentIndex === 1) {
+            if (root.sideBarItem !== null && root.sideBarItem.currentIndex > 0 && stackView.showingAllApps) {
                 stackView.replace(stackView.preferredAllAppsViewComponent)
             }
         }
         onPreferredAppsViewComponentChanged: {
-            if (root.sideBarItem !== null && root.sideBarItem.currentIndex > 1) {
+            if (root.sideBarItem !== null && root.sideBarItem.currentIndex > 0 && !stackView.showingAllApps) {
                 stackView.replace(stackView.preferredAppsViewComponent)
             }
         }
@@ -274,10 +275,10 @@ BasePage {
                 if (root.sideBarItem.currentIndex === 0
                     && stackView.currentItem.objectName !== stackView.preferredFavoritesViewObjectName) {
                     stackView.replace(stackView.preferredFavoritesViewComponent)
-                } else if (root.sideBarItem.currentIndex === 1
+                } else if (root.sideBarItem.currentIndex > 0 && stackView.showingAllApps
                     && stackView.currentItem.objectName !== stackView.preferredAllAppsViewObjectName) {
                     stackView.replace(stackView.preferredAllAppsViewComponent)
-                } else if (root.sideBarItem.currentIndex > 1
+                } else if (root.sideBarItem.currentIndex > 0 && !stackView.showingAllApps
                     && stackView.currentItem.objectName !== stackView.preferredAppsViewObjectName) {
                     stackView.replace(stackView.preferredAppsViewComponent)
                 }
diff --git a/applets/kickoff/ConfigGeneral.qml b/applets/kickoff/ConfigGeneral.qml
index 025cba4c49..102810649c 100644
--- a/applets/kickoff/ConfigGeneral.qml
+++ b/applets/kickoff/ConfigGeneral.qml
@@ -39,6 +39,8 @@ KCM.SimpleKCM {
     property alias cfg_compactMode: compactModeCheckbox.checked
     property alias cfg_highlightNewlyInstalledApps: highlightNewlyInstalledAppsCheckbox.checked
     property alias cfg_switchCategoryOnHover: switchCategoryOnHoverCheckbox.checked
+    property alias cfg_showRecentApps: showRecentAppsCheckbox.checked
+    property alias cfg_showRecentDocs: showRecentDocsCheckbox.checked

     Kirigami.FormLayout {
         QQC2.Button {
@@ -203,6 +205,21 @@ KCM.SimpleKCM {
             Kirigami.FormData.isSection: true
         }

+        QQC2.CheckBox {
+            id: showRecentAppsCheckbox
+            Kirigami.FormData.label: i18nc("@title:group prefix for checkbox group", "Show categories:")
+            text: i18nc("@option:check", "Recent applications")
+        }
+
+        QQC2.CheckBox {
+            id: showRecentDocsCheckbox
+            text: i18nc("@option:check", "Recent files")
+        }
+
+        Item {
+            Kirigami.FormData.isSection: true
+        }
+
         QQC2.RadioButton {
             id: paneSwapOff
             Kirigami.FormData.label: i18nc("@label:group prefix for radio button group", "Sidebar position:")
diff --git a/applets/kickoff/main.qml b/applets/kickoff/main.qml
index 6b6c95dabe..89e27738b5 100644
--- a/applets/kickoff/main.qml
+++ b/applets/kickoff/main.qml
@@ -63,12 +63,20 @@ PlasmoidItem {

         showAllApps: true
         showAllAppsCategorized: false
-        showRecentApps: false
-        showRecentDocs: false
+        showRecentApps: Plasmoid.configuration.showRecentApps
+        showRecentDocs: Plasmoid.configuration.showRecentDocs
         showPowerSession: false
         showFavoritesPlaceholder: true
         highlightNewlyInstalledApps: Plasmoid.configuration.highlightNewlyInstalledApps

+        onShowRecentAppsChanged: {
+            Plasmoid.configuration.showRecentApps = showRecentApps;
+        }
+
+        onShowRecentDocsChanged: {
+            Plasmoid.configuration.showRecentDocs = showRecentDocs;
+        }
+
         Component.onCompleted: {
             favoritesModel.initForClient("org.kde.plasma.kickoff.favorites.instance-" + Plasmoid.id)

diff --git a/applets/kickoff/main.xml b/applets/kickoff/main.xml
index 8f6a44e2a4..3147aa75c5 100644
--- a/applets/kickoff/main.xml
+++ b/applets/kickoff/main.xml
@@ -73,5 +73,13 @@
             <label>Whether to highlight newly-installed applications</label>
             <default>true</default>
         </entry>
+        <entry name="showRecentApps" type="Bool">
+            <label>Whether to show the "Recent Applications" category</label>
+            <default>true</default>
+        </entry>
+        <entry name="showRecentDocs" type="Bool">
+            <label>Whether to show the "Recent Files" category</label>
+            <default>true</default>
+        </entry>
     </group>
 </kcfg>
-- 
2.53.0

From 61bc0b84fc22bd6a94186e1d6f782a467eac6c56 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 23:12:00 +0100
Subject: [PATCH] applets/kicker: keep Favorites above the recent categories

Kickoff needs Favorites as the first sidebar row, but its placeholder
was added before the recent groups and so ended up below them. Add it
last, and give recent apps a compact name like other app entries.

BUG: 442981
---
 applets/kicker/recentusagemodel.cpp |  6 +++++
 applets/kicker/rootmodel.cpp        | 36 ++++++++++++++---------------
 2 files changed, 24 insertions(+), 18 deletions(-)

diff --git a/applets/kicker/recentusagemodel.cpp b/applets/kicker/recentusagemodel.cpp
index e28299e899..f03827afea 100644
--- a/applets/kicker/recentusagemodel.cpp
+++ b/applets/kicker/recentusagemodel.cpp
@@ -202,6 +202,12 @@ QVariant RecentUsageModel::appData(const QString &resource, int role) const
         } else {
             return AppEntry::nameFromService(service, AppEntry::NameOnly);
         }
+    } else if (role == Kicker::CompactNameRole) {
+        auto *parentModel = qobject_cast<AppsModel *>(QObject::parent());
+        const bool genericName =
+            parentModel && (parentModel->appNameFormat() == AppEntry::GenericNameOnly || parentModel->appNameFormat() == AppEntry::GenericNameAndName);
+
+        return AppEntry::nameFromService(service, genericName ? AppEntry::GenericNameOnly : AppEntry::NameOnly);
     } else if (role == Qt::DecorationRole) {
         return service->icon();
     } else if (role == Kicker::DescriptionRole) {
diff --git a/applets/kicker/rootmodel.cpp b/applets/kicker/rootmodel.cpp
index 859c1d5dab..6d9f20abc2 100644
--- a/applets/kicker/rootmodel.cpp
+++ b/applets/kicker/rootmodel.cpp
@@ -557,24 +557,6 @@ void RootModel::refresh()
         ++separatorPosition;
     }

-    if (m_showFavoritesPlaceholder) {
-        // This entry is a placeholder and shouldn't ever be visible
-        QList<AbstractEntry *> placeholderList;
-        auto *placeholderModel = new AppsModel(placeholderList, false, this);
-
-        // Favorites group containing a placeholder entry, so it would be considered as a group, not an entry
-        QList<AbstractEntry *> placeholderEntry;
-        placeholderEntry.append(new GroupEntry(this, //
-                                               i18n("This shouldn't be visible! Use KICKER_FAVORITES_MODEL"),
-                                               QStringLiteral("dialog-warning"),
-                                               placeholderModel));
-        auto *favoritesPlaceholderModel = new AppsModel(placeholderEntry, false, this);
-
-        favoritesPlaceholderModel->setDescription(QStringLiteral("KICKER_FAVORITES_MODEL")); // Intentionally no i18n.
-        m_entryList.prepend(new GroupEntry(this, i18n("Favorites"), QStringLiteral("bookmarks"), favoritesPlaceholderModel));
-        ++separatorPosition;
-    }
-
     if (m_showRecentFolders) {
         m_recentFoldersModel = new RecentUsageModel(this, RecentUsageModel::OnlyFolders, m_recentOrdering);
         m_entryList.prepend(new GroupEntry(this,
@@ -602,6 +584,24 @@ void RootModel::refresh()
         ++separatorPosition;
     }

+    if (m_showFavoritesPlaceholder) {
+        // This entry is a placeholder and shouldn't ever be visible
+        QList<AbstractEntry *> placeholderList;
+        auto *placeholderModel = new AppsModel(placeholderList, false, this);
+
+        // Favorites group containing a placeholder entry, so it would be considered as a group, not an entry
+        QList<AbstractEntry *> placeholderEntry;
+        placeholderEntry.append(new GroupEntry(this, //
+                                               i18n("This shouldn't be visible! Use KICKER_FAVORITES_MODEL"),
+                                               QStringLiteral("dialog-warning"),
+                                               placeholderModel));
+        auto *favoritesPlaceholderModel = new AppsModel(placeholderEntry, false, this);
+
+        favoritesPlaceholderModel->setDescription(QStringLiteral("KICKER_FAVORITES_MODEL")); // Intentionally no i18n.
+        m_entryList.prepend(new GroupEntry(this, i18n("Favorites"), QStringLiteral("bookmarks"), favoritesPlaceholderModel));
+        ++separatorPosition;
+    }
+
     if (m_showRootSeparator && separatorPosition > 0) {
         m_entryList.insert(separatorPosition, new SeparatorEntry(this));
         ++m_separatorCount;
-- 
2.53.0
